static int n;static void Check(bool x,string s){n++;if(!x)throw new Exception(s);}static void Reject(Action a,string s){bool bad=false;try{a();}catch(InvalidDataException){bad=true;}Check(bad,s);}static GroundingSource Source(EarthingScheme scheme){return new GroundingSource{Scheme=scheme,NeutralConnection=scheme==EarthingScheme.IT?NeutralEarthConnection.Isolated:NeutralEarthConnection.Direct,NeutralDistributed=true,InstallationRaOhm=100,SourceRbOhm=2,Reference="Projeto QA Ω",DataVersion="2026.10",Conditions="Grupo único de massas e PE"};}static CircuitConductors W(bool pen=false){return new CircuitConductors{Connection=LiveConnection.LineNeutral,HasNeutral=!pen,HasPE=!pen,HasPEN=pen,Insulation=EquipmentInsulation.ClassI,Reference="Ligação sintética"};}
[STAThread]static int Main(){try{var p=new Project();p.Source.LineVoltage=400;var a=new Board{Id="A",Name="Raiz",Voltage=400};var b=new Board{Id="B",Name="Separação PEN",Voltage=400};p.Boards.AddRange(new[]{a,b});var feeder=DiagramEditing.Connect(p,a,b);var c=new Circuit{Id="L",Voltage=400/Math.Sqrt(3),PowerKw=2,Phases=PhaseMode.Monofasico};c.Protection.RcdMilliA=30;c.Protection.EarthResistanceOhm=9999;b.Circuits.Add(c);Grounding.ApplySource(p,Source(EarthingScheme.TT));Grounding.ApplyConductors(p,c,W());Check(p.Earthing=="TT"&&p.GroundingSource!=null,"typed source synchronizes legacy scheme");Check(Grounding.Ra(p,c)==100&&c.Protection.EarthResistanceOhm==9999,"typed Ra authoritative preserves legacy");Check(Engineering.Analyze(p).Checks.Any(x=>x.CircuitId==c.Id&&x.Rule.Contains("TT: Ra")&&x.Status=="OK"),"TT uses authoritative Ra");Check(Grounding.Describe(p,c).StartsWith("Topologia declarada consistente"),"complete topology described");var source=p.GroundingSource.Copy();source.InstallationRaOhm=null;Grounding.ApplySource(p,source);Check(!Grounding.Ra(p,c).HasValue&&Grounding.Describe(p,c).StartsWith("Dados incompletos"),"unknown Ra no legacy fallback");source.InstallationRaOhm=0;Grounding.ApplySource(p,source);Check(Grounding.Ra(p,c)==0,"zero ideal distinct unknown");source.InstallationRaOhm=-1;Reject(()=>Grounding.ApplySource(p,source),"negative Ra");Check(p.GroundingSource.InstallationRaOhm==0,"failed source atomic");source=Source(EarthingScheme.TT);source.NeutralConnection=NeutralEarthConnection.Isolated;Reject(()=>Grounding.ApplySource(p,source),"TT cannot isolated");source=Source(EarthingScheme.IT);source.NeutralConnection=NeutralEarthConnection.Direct;Reject(()=>Grounding.ApplySource(p,source),"IT cannot direct");source=Source(EarthingScheme.IT);source.GroundingROhm=1000;Reject(()=>Grounding.ApplySource(p,source),"ignored grounding impedance rejected");source.NeutralConnection=NeutralEarthConnection.Impedance;source.GroundingROhm=0;source.GroundingXOhm=0;Reject(()=>Grounding.ApplySource(p,source),"zero Z not isolated");source.GroundingROhm=1000;Grounding.ApplySource(p,source);Check(Grounding.EffectiveSystem(p,c)=="IT","IT stored independent of fault model");source.GroundingXOhm=null;Grounding.ApplySource(p,source);Check(Grounding.Describe(p,c).StartsWith("Dados incompletos"),"unknown grounding X pending");source=Source(EarthingScheme.TNS);Grounding.ApplySource(p,source);var w=W(true);Reject(()=>Grounding.ApplyConductors(p,c,w),"PEN forbidden TNS");Check(c.Conductors.HasPE==true,"invalid wire atomic");w=W();w.HasPEN=true;Reject(()=>Grounding.ApplyConductors(p,c,w),"PEN mixed N PE");w=W();w.HasPE=false;Reject(()=>Grounding.ApplyConductors(p,c,w),"classI requires PE");w.Insulation=EquipmentInsulation.ClassII;Grounding.ApplyConductors(p,c,w);Check(c.Conductors.HasPE==false,"classII can omit PE");w=W();w.HasNeutral=false;Reject(()=>Grounding.ApplyConductors(p,c,w),"LN requires N");w=W();w.Connection=LiveConnection.LineLine;Reject(()=>Grounding.ApplyConductors(p,c,w),"connection voltage mismatch");w=W();w.Connection=LiveConnection.ThreePhaseNeutral;Reject(()=>Grounding.ApplyConductors(p,c,w),"phase count mismatch");w=W();Grounding.ApplyConductors(p,c,w);source=Source(EarthingScheme.TNS);source.NeutralDistributed=false;Reject(()=>Grounding.ApplySource(p,source),"source without neutral cannot feed LN");Check(p.GroundingSource.NeutralDistributed==true,"neutral source rollback");var feederW=new CircuitConductors{Connection=LiveConnection.ThreePhase,HasNeutral=false,HasPE=true,HasPEN=false,Insulation=EquipmentInsulation.ClassI,Reference="feeder no N"};Reject(()=>Grounding.ApplyConductors(p,feeder,feederW),"upstream missing neutral rejected");Check(feeder.Conductors==null,"feeder assignment rolled back");source=Source(EarthingScheme.TNC);Reject(()=>Grounding.ApplySource(p,source),"RCD combined TN-C rejected");c.Protection.RcdMilliA=0;c.Conductors=null;Grounding.ApplySource(p,source);Grounding.ApplyConductors(p,c,W(true));Check(Grounding.EffectiveSystem(p,c)=="TN-C","PEN combined accepted");b.SeparatesPEN=true;Reject(p.Validate,"TNC cannot split marker");b.SeparatesPEN=false;source=Source(EarthingScheme.TNCS);Grounding.ApplySource(p,source);Check(Grounding.Combined(p,b),"TNCS upstream combined by default");b.SeparatesPEN=true;Reject(p.Validate,"cannot retain PEN after split");c.Conductors=W();p.Validate();Check(!Grounding.Combined(p,b)&&Grounding.Combined(p,a),"split applies outgoing only");Grounding.ApplyConductors(p,feeder,new CircuitConductors{Connection=LiveConnection.ThreePhaseNeutral,HasNeutral=false,HasPE=false,HasPEN=true,Insulation=EquipmentInsulation.ClassI,Reference="PEN antes da separação"});c.Protection.RcdMilliA=30;p.Validate();Check(Grounding.EffectiveSystem(p,c)=="TN-S","RCD allowed after split");var d=new Board{Id="D",Voltage=400};p.Boards.Add(d);var bd=DiagramEditing.Connect(p,b,d);d.SeparatesPEN=true;Reject(p.Validate,"second split would reunite PEN");d.SeparatesPEN=false;Check(!Grounding.Combined(p,d),"separation inherited downstream");w=W(true);var dc=new Circuit{Id="DL",Voltage=c.Voltage};d.Circuits.Add(dc);Reject(()=>Grounding.ApplyConductors(p,dc,w),"PEN cannot reappear downstream");Grounding.ApplyConductors(p,dc,W());p.Validate();var invalidSource=p.GroundingSource.Copy();invalidSource.Engine="future";Reject(()=>Grounding.ApplySource(p,invalidSource),"unknown engine apply");invalidSource=p.GroundingSource.Copy();invalidSource.InstallationRaOhm=double.NaN;Reject(()=>Grounding.ApplySource(p,invalidSource),"nonfinite resistance");invalidSource=p.GroundingSource.Copy();invalidSource.Scheme=(EarthingScheme)99;Reject(()=>Grounding.ApplySource(p,invalidSource),"unknown scheme enum");var incomplete=c.Conductors.Copy();incomplete.HasPE=null;Grounding.ApplyConductors(p,c,incomplete);Check(!Grounding.Complete(p,c),"unknown PE stays pending");incomplete=W();incomplete.Reference="";Grounding.ApplyConductors(p,c,incomplete);Check(!Grounding.Complete(p,c),"missing wire evidence pending");Grounding.ApplyConductors(p,c,W());incomplete=W();Grounding.ApplyConductors(p,c,incomplete);incomplete.HasPE=false;Check(c.Conductors.HasPE==true,"applied wire snapshot independent");var snapshot=p.GroundingSource.Copy();Grounding.ApplySource(p,snapshot);snapshot.Reference="changed outside";Check(p.GroundingSource.Reference!="changed outside","source snapshot independent");string folder=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"referencias-aterramento");Directory.CreateDirectory(folder);string file=Path.Combine(folder,"rede.circuito");p.Save(file);string saved=File.ReadAllText(file);Check(saved.Contains("earthing-conductors-v1")&&saved.Contains("\"FileVersion\":4"),"new capability guard");var loaded=Project.Load(file);Check(loaded.Boards[1].SeparatesPEN&&loaded.Boards[0].Circuits[0].Conductors.HasPEN==true,"source split and conductors persist");Check(EngineeringReport.Memory(p,Engineering.Analyze(p))==EngineeringReport.Memory(loaded,Engineering.Analyze(loaded)),"full report reproduces");var copy=ProjectEditing.DuplicateCircuit(p,b,c);Check(copy.Conductors!=c.Conductors&&copy.Conductors.HasPE==true,"deep copy conductors");b.Circuits.Remove(copy);File.WriteAllText(file,saved.Replace(Grounding.EngineId,"future-earth"));Reject(()=>Project.Load(file),"unknown evaluator rejected");File.WriteAllText(file,saved);string previous=Environment.GetEnvironmentVariable("CIRCUITO_QA_PREVIOUS_EXE");if(!String.IsNullOrEmpty(previous)){var assembly=Assembly.LoadFile(Path.GetFullPath(previous));bool bad=false;try{assembly.GetType("CircuitoStudio.Project").GetMethod("Load").Invoke(null,new object[]{file});}catch(TargetInvocationException ex){bad=ex.InnerException is InvalidDataException;}Check(bad,"actual previous reader refuses new grounding model");}var old=p.GroundingSource;p.GroundingSource=null;Reject(p.Validate,"wiring cannot silently exist without source model");p.GroundingSource=old;string oldScheme=p.Earthing;p.Earthing="TT";Reject(p.Validate,"legacy typed mismatch");p.Earthing=oldScheme;File.WriteAllText(Path.Combine(folder,"memoria.txt"),EngineeringReport.Memory(p,Engineering.Analyze(p)));using(var form=new GroundingForm(p,b,c)){Check(!form.Changed,"open panel no mutation");form.ApplyDraft();Check(form.Changed&&Grounding.Complete(p,c),"typed form applies explicit fields");var layout=form.Controls.OfType<TableLayoutPanel>().First();var sourceEditor=layout.Controls.OfType<TableLayoutPanel>().First();TextBox raInput=null;for(int i=0;i<sourceEditor.RowCount;i++){var label=sourceEditor.GetControlFromPosition(0,i) as Label;if(label!=null&&label.Text.StartsWith("Ra da"))raInput=sourceEditor.GetControlFromPosition(1,i) as TextBox;}Check(raInput!=null,"visible Ra editor identified");var oldDraftSource=p.GroundingSource;raInput.Text="-1";Reject(form.ApplyDraft,"invalid form cannot commit");Check(Object.ReferenceEquals(oldDraftSource,p.GroundingSource),"failed form preserves source object");raInput.Text="100";form.ApplyDraft();if(Environment.GetEnvironmentVariable("CIRCUITO_QA_VISUAL")=="1"){form.StartPosition=FormStartPosition.Manual;form.Location=new Point(10,10);form.Show();Application.DoEvents();form.Refresh();form.Update();using(var bitmap=new Bitmap(form.ClientSize.Width,form.ClientSize.Height)){using(var g=Graphics.FromImage(bitmap))g.CopyFromScreen(form.PointToScreen(Point.Empty),Point.Empty,form.ClientSize);bitmap.Save(Path.Combine(folder,"aterramento.png"));}form.Hide();}}Console.WriteLine("PASS: "+n+" grounding topology assertions");return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
